432\\u0435\\u0440\\u043a\\u0438 \\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441\\u0430: \\u043e\\u0434\\u043d\\u0430 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c-API-\\u043a\\u043b\\u0430\\u0441\\u0441\\u0430 (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, GPT-3.5-\\u0443\\u0440\\u043e\\u0432\\u043d\\u044f) \\u2014 \\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0441\\u0443\\u0444\\u0444\\u0438\\u043a\\u0441\\u0430. \\u041c\\u0435\\u0442\\u043e\\u0434 \\u0441\\u0443\\u0444\\u0444\\u0438\\u043a\\u0441\\u0430: GCG (greedy coordinate gradient, Zou et al. 2023) \\u0437\\u0430 \\u043e\\u043a\\u043d\\u043e\\u043c \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438; \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u2014 transfer-\\u0430\\u0442\\u0430\\u043a\\u0430 (\\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0441\\u0443\\u0444\\u0444\\u0438\\u043a\\u0441, \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043d\\u0430 \\u0441\\u0443\\u0440\\u0440\\u043e\\u0433\\u0430\\u0442\\u0435). GCG \\u0432\\u044b\\u0431\\u0440\\u0430\\u043d \\u043a\\u0430\\u043a \\u043a\\u0430\\u043d\\u043e\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u00abtoken-level\\u00bb \\u043c\\u0435\\u0442\\u043e\\u0434, \\u0433\\u0434\\u0435 \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0441\\u0443\\u0444\\u0444\\u0438\\u043a\\u0441\\u0430 \\u2014 \\u044f\\u0432\\u043d\\u044b\\u0439 \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u044f\\u0435\\u043c\\u044b\\u0439 \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440.\\n\\n**(\\u0431) ASR.** \\u0415\\u0434\\u0438\\u043d\\u0438\\u0446\\u0430 \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430 \\u2014 \\u0442\\u0440\\u043e\\u0435\\u0447\\u043a\\u0430 (\\u043f\\u043e\\u0432\\u0435\\u0434\\u0435\\u043d\\u0438\\u0435 \\u00d7 \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u044b\\u0439 \\u0441\\u0443\\u0444\\u0444\\u0438\\u043a\\u0441 \\u00d7 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u00d7 \\u0441\\u0438\\u0434), \\u0438\\u0442\\u043e\\u0433 \\u0431\\u0438\\u043d\\u0430\\u0440\\u043d\\u044b\\u0439. \\u00ab\\u0423\\u0441\\u043f\\u0435\\u0445\\u00bb = \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442 GCG/AdvBench: \\u043e\\u0442\\u0432\\u0435\\u0442 **\\u043d\\u0435** \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u043d\\u0438 \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e \\u043c\\u0430\\u0440\\u043a\\u0435\\u0440\\u0430 \\u043e\\u0442\\u043a\\u0430\\u0437\\u0430 \\u0438\\u0437 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e refusal-\\u0441\\u043f\\u0438\\u0441\\u043a\\u0430 \\u0418 \\u0441\\u043e\\u0432\\u043f\\u0430\\u0434\\u0430\\u0435\\u0442 \\u0441 affirmative-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d\\u043e\\u043c (\\u00abSure, here is\\u2026\\u00bb) \\u0432 \\u043d\\u0430\\u0447\\u0430\\u043b\\u0435; \\u0432\\u0442\\u043e\\u0440\\u0430\\u044f, \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u0430\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u2014 \\u0441\\u0443\\u0434\\u044c\\u044f-LLM (\\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c, \\u0441\\u0432\\u043e\\u0439 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442-\\u0441\\u043f\\u0435\\u043a\\u0430) \\u0441 \\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0440\\u0443\\u0447\\u043d\\u043e\\u0439 \\u0432\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u0435\\u0439 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0445 ~10% \\u043e\\u0442\\u0432\\u0435\\u0442\\u043e\\u0432 \\u0438 \\u0441\\u043e\\u0433\\u043b\\u0430\\u0441\\u0438\\u0435\\u043c (Cohen's \\u03ba \\u2265 0.8) \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0434\\u0432\\u0443\\u043c\\u044f \\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u0430\\u043c\\u0438. ASR = \\u0434\\u043e\\u043b\\u044f \\u0443\\u0441\\u043f\\u0435\\u0445\\u043e\\u0432 \\u0432 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0435 (\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u00d7 \\u0434\\u043b\\u0438\\u043d\\u0430 \\u00d7 \\u043c\\u0435\\u0442\\u043e\\u0434 \\u00d7 \\u0442\\u0438\\u043f \\u0441\\u0443\\u0444\\u0444\\u0438\\u043a\\u0441\\u0430) \\u0441 95% Wilson-\\u0438\\u043d\\u0442\\u0435\\u0440\\u0432\\u0430\\u043b\\u043e\\u043c.\\n\\n**(\\u0432) \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0434\\u043b\\u0438\\u043d\\u044b \\u0438 \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 \\u00ab\\u0434\\u043b\\u0438\\u043d\\u0430 vs \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u043c\\u043e\\u0435\\u00bb.** \\u0414\\u043b\\u0438\\u043d\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0451\\u0442\\u0441\\u044f \\u0441\\u0442\\u0440\\u043e\\u0433\\u043e \\u0432 \\u0442\\u043e\\u043a\\u0435\\u043d\\u0430\\u0445 \\u0446\\u0435\\u043b\\u0435\\u0432\\u043e\\u0433\\u043e \\u0442\\u043e\\u043a\\u0435\\u043d\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0430; \\u0443\\u0440\\u043e\\u0432\\u043d\\u0438 \\u043b\\u043e\\u0433\\u0430\\u0440\\u0438\\u0444\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0438: 10, 20, 30, 40, 50, 64, 80, 100, 128, 160, 200, 256. \\u0414\\u0432\\u0435 \\u0432\\u0437\\u0430\\u0438\\u043c\\u043e\\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u044f\\u044e\\u0449\\u0438\\u0435 \\u0441\\u0445\\u0435\\u043c\\u044b: (1) **\\u0432\\u043b\\u043e\\u0436\\u0435\\u043d\\u043d\\u044b\\u0435 \\u043f\\u0440\\u0435\\u0444\\u0438\\u043a\\u0441\\u044b** \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e GCG-\\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u0441\\u0443\\u0444\\